import math

def check_condition(n):
    """
    Checks if for all k coprime to n, k^2 - 1 is divisible by n.
    """
    if n < 2:
        return False # Should not happen based on problem constraints

    for k in range(1, n):
        if math.gcd(k, n) == 1:
            # Check if k^2 - 1 is a multiple of n
            if (k*k - 1) % n != 0:
                print(f"N={n} failed for k={k}. (k^2 - 1) mod n = {(k*k - 1) % n}")
                return False
    print(f"N={n} passed.")
    return True

N_to_test = [4, 6, 8, 9, 10, 12, 14, 15]
results = {}
for n in N_to_test:
    results[n] = check_condition(n)

print("\n--- Summary ---")
print(results)

